const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '../..');
const LANG_PATH = path.join(ROOT, 'language/en.json');

const APPS = [
    {
        id: 'shape',
        profile: 'ui/profile-shape.json',
        page: 'easyshape5000/doc/parameters.html',
        skipOps: ['pattern', 'unassigned']
    },
    {
        id: 'trace',
        profile: 'ui/profile-trace.json',
        page: 'easytrace5000/doc/parameters.html',
        skipOps: []
    }
];

const TOC_BEGIN = '<!-- PARAMS-TOC:BEGIN - generated by build-doc-params.js, do not edit -->';
const TOC_END = '<!-- PARAMS-TOC:END -->';
const BODY_BEGIN = '<!-- PARAMS:BEGIN - generated by build-doc-params.js, do not edit -->';
const BODY_END = '<!-- PARAMS:END -->';

const esc = s => String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const read = p => JSON.parse(fs.readFileSync(p, 'utf8'));

/** Stage order is the union of every chain's stage list, in chain order. */
function stageOrder(profile) {
    const seen = [];
    for (const chain of Object.values(profile.chains || {})) {
        for (const s of chain.stages || []) if (!seen.includes(s)) seen.push(s);
    }
    return seen;
}

function stageLabel(profile, stage) {
    return profile.ui?.stages?.[stage]?.label || stage;
}

function categoryLabel(profile, category) {
    return profile.ui?.categories?.[category] || category;
}

/** Parameters this app actually exposes, keyed stage -> category -> [param]. */
function collect(profile, skipOps) {
    const out = new Map();
    for (const [name, def] of Object.entries(profile.parameters || {})) {
        if (name.startsWith('_')) continue;
        if (!def || typeof def !== 'object' || !def.stage) continue;

        const ops = def.operationTypes == null
            ? null
            : (Array.isArray(def.operationTypes) ? def.operationTypes : [def.operationTypes]);
        if (ops && ops.length && ops.every(o => skipOps.includes(o))) continue;

        const stage = def.stage;
        const category = def.category || 'general';
        if (!out.has(stage)) out.set(stage, new Map());
        const cats = out.get(stage);
        if (!cats.has(category)) cats.set(category, []);
        cats.get(category).push({ name, def, ops });
    }
    return out;
}

function rangeCell(def, lang) {
    if (Array.isArray(def.options)) {
        return def.options
            .map(o => esc(lang.enums?.[o.value] || o.label || o.value))
            .join(' / ');
    }
    if (def.type === 'checkbox' || def.type === 'boolean') return 'on / off';
    if (def.min !== undefined && def.max !== undefined) {
        return `${def.min} - ${def.max}${def.unit ? ' ' + esc(def.unit) : ''}`;
    }
    if (def.type === 'select') return 'tool library';
    return '&mdash;';
}

function defaultCell(def, lang) {
    if (def.default === undefined || def.default === null || def.default === '') return '&mdash;';
    if (def.default === true) return 'on';
    if (def.default === false) return 'off';
    if (Array.isArray(def.options)) {
        const hit = def.options.find(o => String(o.value) === String(def.default));
        if (hit) return esc(lang.enums?.[hit.value] || hit.label || hit.value);
    }
    return esc(def.default);
}

function appliesCell(entry, profile) {
    if (!entry.ops || !entry.ops.length) return 'all operations';
    return entry.ops.map(o => esc(profile.operations?.[o]?.label || o)).join(', ');
}

/**
 * Conditionals are the single most common support question: a field that is
 * declared but gated reads to the user as a missing field.
 */
function conditionCell(def, profile, lang) {
    if (!def.conditional) return '';

    const nameOf = key => lang.params?.[key]?.label || profile.parameters?.[key]?.label || key;
    const valueOf = (key, value) => {
        const opts = profile.parameters?.[key]?.options;
        const hit = Array.isArray(opts) && opts.find(o => String(o.value) === String(value));
        return hit ? (lang.enums?.[hit.value] || hit.label || hit.value) : value;
    };

    const human = String(def.conditional)
        .split('&&')
        .map(part => {
            const t = part.trim();
            if (t.startsWith('!')) return `${nameOf(t.slice(1))} is off`;
            const [k, v] = t.split(':');
            if (!v) return `${nameOf(k)} is on`;
            return `${nameOf(k)} is ${v.split(',').map(x => valueOf(k, x)).join(' or ')}`;
        })
        .join(' and ');

    return `<br><span class="param-condition">Shown when ${esc(human)}</span>`;
}

function classCell(def) {
    if (!Array.isArray(def.machineClasses)) return '';
    return `<br><span class="param-condition">Machine class: ${esc(def.machineClasses.join(', '))}</span>`;
}

function buildApp(app, lang) {
    const profile = read(path.join(ROOT, app.profile));
    const grouped = collect(profile, app.skipOps);
    const missing = [];
    const toc = [];
    const body = [];

    for (const stage of stageOrder(profile)) {
        if (!grouped.has(stage)) continue;
        const cats = grouped.get(stage);
        const stageId = `stage-${stage}`;
        toc.push(`                <li><a href="#${stageId}" draggable="false">${esc(stageLabel(profile, stage))}</a></li>`);

        body.push(`            <section id="${stageId}">`);
        body.push(`                <h2>${esc(stageLabel(profile, stage))}</h2>`);

        for (const [category, list] of cats) {
            body.push(`                <h3>${esc(categoryLabel(profile, category))}</h3>`);
            body.push('                <table>');
            body.push('                    <thead>');
            body.push('                        <tr><th scope="col">Parameter</th><th scope="col">Values</th><th scope="col">Default</th><th scope="col">Applies to</th><th scope="col">What it does</th></tr>');
            body.push('                    </thead>');
            body.push('                    <tbody>');

            for (const entry of list) {
                const langEntry = lang.params?.[entry.name];
                if (!langEntry || !langEntry.help) {
                    missing.push(`${app.id}:${entry.name}`);
                    continue;
                }
                const label = langEntry.label || entry.def.label || entry.name;
                body.push('                        <tr>');
                body.push(`                            <td><strong>${esc(label)}</strong>${conditionCell(entry.def, profile, lang)}${classCell(entry.def)}</td>`);
                body.push(`                            <td>${rangeCell(entry.def, lang)}</td>`);
                body.push(`                            <td>${defaultCell(entry.def, lang)}</td>`);
                body.push(`                            <td>${appliesCell(entry, profile)}</td>`);
                body.push(`                            <td>${esc(langEntry.help)}</td>`);
                body.push('                        </tr>');
            }

            body.push('                    </tbody>');
            body.push('                </table>');
        }
        body.push('            </section>');
        body.push('');
    }

    return { toc: toc.join('\n'), body: body.join('\n'), missing };
}

function replaceRegion(text, begin, end, content, file) {
    const i = text.indexOf(begin);
    const j = text.indexOf(end);
    if (i === -1 || j === -1 || j < i) {
        console.error(`❌ ${file}: missing marker pair ${begin} / ${end}`);
        process.exit(1);
    }
    return text.slice(0, i + begin.length) + '\n' + content + '\n' + text.slice(j);
}

const lang = read(LANG_PATH);
const allMissing = [];
const writes = [];

for (const app of APPS) {
    const pagePath = path.join(ROOT, app.page);
    if (!fs.existsSync(pagePath)) {
        console.error(`❌ Target page not found: ${app.page}`);
        process.exit(1);
    }
    const built = buildApp(app, lang);
    allMissing.push(...built.missing);

    let html = fs.readFileSync(pagePath, 'utf8');
    html = replaceRegion(html, TOC_BEGIN, TOC_END, built.toc, app.page);
    html = replaceRegion(html, BODY_BEGIN, BODY_END, built.body, app.page);
    writes.push([pagePath, html, app.page]);
}

// Gate: a parameter with no en.json entry renders with no tooltip in the app
// and cannot be documented here. Fix the string pack, not this script.
if (allMissing.length) {
    console.error(`❌ No language/en.json params entry (or no .help) for:\n   ${allMissing.join('\n   ')}`);
    process.exit(1);
}

for (const [p, html, label] of writes) {
    fs.writeFileSync(p, html, 'utf8');
    console.log(`✅ ${label} parameter tables regenerated`);
}